    it('should return mocked data when calling getData', () => {
        // Create a stub for the getData method
        const getDataStub = sandbox.stub(sensorAgentApi, 'getData').returns({ data: 'mocked data' });

        // Call the method
        const data = sensorAgentApi.getData();

        // Assert the result
        assert.deepStrictEqual(data, { data: 'mocked data' });

        // Verify the method was called
        assert(getDataStub.calledOnce);
    });

    it('should send mocked data when calling sendData', () => {
        // Create a spy for the sendData method
        const sendDataSpy = sandbox.spy(sensorAgentApi, 'sendData');

        // Call the method with some data
        sensorAgentApi.sendData({ data: 'mocked data' });

        // Verify the method was called with the correct arguments
        assert(sendDataSpy.calledWithExactly({ data: 'mocked data' }));
    });
});
