    <test name="UnitTests">
        <packages>
            <package name="com.example.unit.*"/>
        </packages>
    </test>

    <test name="IntegrationTests">
        <packages>
            <package name="com.example.integration.*"/>
        </packages>
    </test>

</suite>
EOF
```

