Here's an example Jenkinsfile that integrates your test suite setup with Jenkins:

```groovy
pipeline {
    agent any

    environment {
        PYTHON_VERSION = '3.10'
    }

    stages {
        stage('Checkout') {
            steps {
                git branch: 'main', url: 'https://your-repo-url.git'
            }
        }

        stage('Setup Environment') {
            steps {
                script {
                    sh 'python3.10 -m venv venv'
                    sh 'source venv/bin/activate && pip install -r requirements.txt'
                }
            }
