                    sh 'source venv/bin/activate && pytest -n ${num_cores}'
                }
            }
        }

        stage('Archive Artifacts') {
            steps {
                archiveArtifacts artifacts: '**/test-reports/*.xml', allowEmptyArchive: true
            }
        }

        stage('Publish Test Results') {
            steps {
                pytest 'test-reports/**/*.xml'
            }
        }
    }

    post {
        always {
            cleanWs()
        }
    }
}
