        - uses: actions/checkout@v2
        - name: Set up Node.js ${{ matrix.node-version }}
          uses: actions/setup-node@v2
          with:
            node-version: ${{ matrix.node-version }}
        - name: Install dependencies
          run: |
            npm ci
        - name: Run tests
          run: |
            npx cypress run --parallel
  ```

