                }
            }
        }
        stage('Setup Grafana') {
            steps {
                script {
                    sh 'docker run -d --name grafana -p 3000:3000 grafana/grafana'
                }
            }
        }
        stage('Analyze Logs') {
            steps {
                script {
                    sh '''
                    cat logs/app.log | jq '.message | select(startswith("Rendering time"))' > logs/rendering_times.log
                    cat logs/app.log | jq '.message | select(startswith("Asset loading time"))' > logs/asset_loading_times.log

                    cat logs/rendering_times.log | jq '.message | sub("Rendering time: "; "") | sub("ms"; "") | tonumber' | awk '{sum+=$1; n++} END {print "Average Rendering Time: " sum/n " ms"}' > logs/average_rendering_time.log

                    cat logs/asset_loading_times.log | jq '.message | sub("Asset loading time: "; "") | sub("ms"; "") | tonumber' | awk '{sum+=$1; n++} END {print "Average Asset Loading Time: " sum/n " ms"}' > logs/average_asset_loading_time.log
                    '''
                }
            }
        }
    }
}
