```python
import carla
import random
import time

# Initialize CARLA and set up the world
client = carla.Client('localhost', 2000)
client.set_timeout(10.0)
world = client.get_world()

# Function to spawn agents
def spawn_agents(world, num_agents):
    blueprint_library = world.get_blueprint_library()
    vehicle_bp = blueprint_library.filter('vehicle')[0]
    spawn_points = world.get_map().get_spawn_points()

    for i in range(num_agents):
        if i < len(spawn_points):
            world.try_spawn_actor(vehicle_bp, spawn_points[i])

# Function to update rendering settings
def update_rendering_settings(world, settings):
    current_settings = world.get_settings()
    current_settings.synchronous_mode = settings['synchronous_mode']
    current_settings.fixed_delta_seconds = settings['fixed_delta_seconds']
    world.apply_settings(current_settings)

# Function to update physics settings
def update_physics_settings(world, settings):
    current_physics_settings = world.get_physics_settings()
    current_physics_settings.substepping = settings['substepping']
    world.apply_physics_settings(current_physics_settings)

# Function to run the simulation
def run_simulation(world, num_steps, step_duration):
    for _ in range(num_steps):
        world.tick(step_duration)

# Stress testing scenarios
scenarios = [
    {
        'name': 'Low Load',
        'num_agents': 10,
        'rendering_settings': {
            'synchronous_mode': True,
            'fixed_delta_seconds': 0.01
        },
        'physics_settings': {
            'substepping': True
        }
    },
    {
        'name': 'Medium Load',
        'num_agents': 50,
        'rendering_settings': {
            'synchronous_mode': True,
            'fixed_delta_seconds': 0.01
        },
        'physics_settings': {
            'substepping': True
        }
    },
    {
        'name': 'High Load',
        'num_agents': 100,
        'rendering_settings': {
            'synchronous_mode': True,
            'fixed_delta_seconds':  0.01
        },
        'physics_settings': {
            'substepping': True
        }
    },
    {
        'name': 'Very High Load',
        'num_agents': 150,
        'rendering_settings': {
            'synchronous_mode': True,
            'fixed_delta_seconds': 0.01
        },
        'physics_settings': {
            'substepping': True
        }
    },
    {
        'name': 'No Substepping',
        'num_agents': 100,
        'rendering_settings': {
            'synchronous_mode': True,
            'fixed_delta_seconds': 0.01
        },
        'physics_settings': {
            'substepping': False
        }
    },
    {
        'name': 'Higher Fixed Delta Seconds',
        'num_agents': 100,
        'rendering_settings': {
            'synchronous_mode': True,
            'fixed_delta_seconds': 0.02
        },
        'physics_settings': {
            'substepping': True
        }
    }
]

# Run each scenario
for scenario in scenarios:
    print(f"Running scenario: {scenario['name']}")

    # Clear existing actors
    for actor in world.get_actors():
        actor.destroy()

    # Spawn agents
    spawn_agents(world, scenario['num_agents'])

    # Update rendering settings
    update_rendering_settings(world, scenario['rendering_settings'])

    # Update physics settings
    update_physics_settings(world, scenario['physics_settings'])

    # Run the simulation
    run_simulation(world, 100, scenario['rendering_settings']['fixed_delta_seconds'])

    # Log results
    print(f"Scenario {scenario['name']} completed successfully.")
    print("--------------------------------------------------")
    time.sleep(2)  # Wait before starting the next scenario

print("All stress testing scenarios completed.")
```

### Explanation

1. **Initialization**: Connect to the CARLA server and get the world.
2. **Helper Functions**:
   - `spawn_agents`: Spawns a specified number of agents in the world.
   - `update_rendering_settings`: Updates the rendering settings.
   - `update_physics_settings`: Updates the physics settings.
   - `run_simulation`: Runs the simulation for a specified number of steps.
3. **Scenarios**: Define multiple scenarios with different numbers of agents, rendering settings, and physics configurations.
4. **Execution Loop**: Iterate through each scenario, clear existing actors, spawn new agents, update settings, run the simulation, and log the results.

### Key Points

- **Clear Existing Actors**: Before each scenario, clear existing actors to ensure a clean start.
- **Scenario Variations**: Include variations in the number of agents, rendering settings, and physics configurations to cover a wide range of conditions.
- **Logging**: Log the completion of each scenario to track progress and results.

