                sh 'coverage xml -o coverage.xml'
            }
        }
    }

    post {
        always {
            // Publish coverage report to Jenkins
            cobertura autoUpdateHealth: false, autoUpdateStability: false, coberturaReportFile: 'coverage.xml', conditionalCoverageTargets: '75, 85, 95', failUnhealthy: true, failUnstable: true, lineCoverageTargets: '75, 85, 95', maxNumberOfBuilds: 50, onDemand: false, recordingPolicy: 'ALWAYS', unstablePercentageTargets: '75, 85, 95'
        }
    }
}
```

### Explanation of Parameters

- **lineCoverageTargets**: Specifies the line coverage targets. The values are provided as a comma-separated list representing the minimum, healthy, and optimal coverage percentages.
- **conditionalCoverageTargets**: Specifies the conditional coverage targets. Similar to `lineCoverageTargets`, these values represent the minimum, healthy, and optimal coverage percentages.
- **unstablePercentageTargets**: Specifies the percentage targets for marking a build as unstable. These values represent the minimum, healthy, and optimal coverage percentages.
- **failUnhealthy**: Determines whether the build should fail if the coverage is below the healthy threshold.
- **failUnstable**: Determines whether the build should fail if the coverage is below the unstable threshold.

### Customizing Values

You can adjust the values in the `lineCoverageTargets`, `conditionalCoverageTargets`, and `unstablePercentageTargets` parameters to fit your project's needs. For example, if you want to set the line coverage targets to 70% minimum, 80% healthy, and 90% optimal, you would set `lineCoverageTargets: '70, 80, 90'`.

